-- Beauty & Salon template suite — additive, idempotent seed migration.
-- Preserves all existing Grocery and other industry catalog rows.
-- Images are original first-party procedural SVGs rendered by storefront.js; no external image URLs.
ON CONFLICT (template_key) DO UPDATE SET category_slug=EXCLUDED.category_slug,name=EXCLUDED.name,tagline=EXCLUDED.tagline,description=EXCLUDED.description,business_types=EXCLUDED.business_types,feature_flags=EXCLUDED.feature_flags,sort_order=EXCLUDED.sort_order,is_builtin=EXCLUDED.is_builtin;

ON CONFLICT (template_key,design_version) DO UPDATE SET design_spec=EXCLUDED.design_spec,preview_settings=EXCLUDED.preview_settings,source_commit=EXCLUDED.source_commit,is_active=EXCLUDED.is_active,updated_at=now();

ON CONFLICT (template_key,page_key) DO UPDATE SET page_type=EXCLUDED.page_type,title=EXCLUDED.title,slug=EXCLUDED.slug,sort_order=EXCLUDED.sort_order,page_spec=EXCLUDED.page_spec,is_required=EXCLUDED.is_required,is_active=EXCLUDED.is_active,updated_at=now();

DO $$
DECLARE t text; pc integer; ac integer; uc integer; bad integer;
BEGIN
 FOREACH t IN ARRAY ARRAY['maison-beauty-spa','the-hair-atelier','forme-nail-brow','the-bridal-edit'] LOOP
  SELECT count(*) INTO pc FROM builder.template_pages WHERE template_key=t AND is_active=true;
  SELECT count(*),count(DISTINCT img->>'id') INTO ac,uc FROM builder.template_pages p CROSS JOIN LATERAL jsonb_array_elements(p.page_spec->'media'->'images') img WHERE p.template_key=t AND p.is_active=true;
  SELECT count(*) INTO bad FROM builder.template_pages p WHERE p.template_key=t AND p.is_active=true AND ((p.page_key='home' AND (jsonb_array_length(p.page_spec->'media'->'images')<>5 OR (p.page_spec->'media'->>'imageCount')::int<>5)) OR (p.page_key<>'home' AND (jsonb_array_length(p.page_spec->'media'->'images')<2 OR jsonb_array_length(p.page_spec->'media'->'images')>4 OR (p.page_spec->'media'->>'imageCount')::int<>jsonb_array_length(p.page_spec->'media'->'images'))));
  IF pc<>40 OR ac<>83 OR uc<>83 OR bad<>0 THEN RAISE EXCEPTION 'Beauty template % failed release counts: pages %, assets %, unique %, bad pages %',t,pc,ac,uc,bad; END IF;
 END LOOP;
END $$;
